function renderReflexes(){const box=document.getElementById('reflexCards');if(!box)return;box.innerHTML='<div class="category-grid">'+Object.entries(REFLEXES).map(([key,v])=>`<button class="action reflex-action" onclick="showReflex('${key}\')"><div class="title-row"><strong>${v.icon} ${v.title}</strong><span class="fav-inline" onclick="event.stopPropagation();toggleFavItem('reflex','${key}\')" aria-label="Favori">${isFavItem('reflex',key)?'★':'☆'}</span></div><span class="small">Fiche réflexe opérationnelle</span></button>`).join('')+'</div>'}
function showReflex(key){const v=REFLEXES[key];document.getElementById('reflexCards').innerHTML=`<div class="reflex-detail"><button class="back" onclick="renderReflexes()">← Sommaire fiches réflexes</button><div class="hero"><div class="title-row"><h1>${v.icon} ${v.title}</h1><button class="fav-inline" onclick="toggleFavItem('reflex','${key}\')" aria-label="Favori">${isFavItem('reflex',key)?'★':'☆'}</button></div><p>Fiche réflexe opérationnelle</p></div><div class="detail-sections-grid">${v.items.map(x=>`<div class="detail-section"><h3>${x[0]}</h3><ul class="detail-list">${x[1].split(/ · | \+ |\n/).filter(Boolean).map(t=>`<li>${t}</li>`).join('')}</ul></div>`).join('')}</div><button class="secondary" onclick="show('home')">← Accueil</button></div>`;window.scrollTo(0,0)}
