function zoomSet(imgs){const g=document.getElementById('docGallery');if(!g)return;g.innerHTML=(imgs||[]).map(src=>`<img src="${escapeHtml(src)}" alt="Document" onclick="document.getElementById('overlay').classList.remove('show')">`).join('');document.getElementById('overlay').classList.add('show')}
function controlImages(p,label){const map=CONTROL_IMAGES[p]||{};const imgs=map[label]||map[Object.keys(map).find(k=>label.startsWith(k))]||[];if(!imgs.length)return "";const js=JSON.stringify(imgs).replace(/</g,'\u003c');return `<button type="button" class="doc-view" aria-label="Visualiser ${label}" title="Visualiser le document" onclick='event.stopPropagation();zoomSet(${js})'>🖼️ Visualiser</button>`}
function renderControl(){const p=current.profession,items=DATA.checklists[p]||[];let statusBlock='';if(p==='VTC'||p==='LOTI')statusBlock=`<div class="card"><h3>Statut du conducteur</h3><p class="small">Sélectionner avant la checklist.</p><div class="selectrow">${['Exploitant','Salarié','Non applicable'].map(st=>`<button class="choice ${current.status===st?'selected':''}" onclick="current.status='${st}';renderControl()">${st}</button>`).join('')}</div></div>`;let done=items.filter((_,i)=>current.answers[i]).length;document.getElementById('controlContent').innerHTML=`<div class="hero"><h1>Contrôle ${p}</h1><p>${done} / ${items.length} éléments renseignés</p></div>${statusBlock}<div class="control-head"><div class="progress"><i style="width:${items.length?Math.round(done/items.length*100):0}%"></i></div></div>${items.map((it,i)=>{let a=current.answers[i],opts=optionsFor(it,p);return `<div class="item"><div class="meta">${it[1]}</div><div class="what">${it[0]}</div>${controlImages(p,it[0])}<div class="verify">${it[2]}</div><div class="statuses">${opts.map(st=>`<button type="button" class="status ${a===st[0]?'sel '+st[2]:''}" aria-pressed="${a===st[0]?'true':'false'}" onclick="setStatus(${i},'${st[0]}')">${st[1]}</button>`).join('')}</div></div>`}).join('')}<button class="primary" onclick="analyze()">Analyser le contrôle</button><button class="secondary" onclick="openReportFromCurrentControl()">📝 Générer un rapport à partir du contrôle</button><button class="secondary" onclick="show('home')">Retour à l’accueil</button>`}
function setStatus(i,s){current.answers[i]=s;renderControl()}
function analyze(){try{const p=current.profession,items=DATA.checklists[p]||[],bad=items.map((it,i)=>({it,i,a:current.answers[i]})).filter(x=>['absent','nonconforme','nonpresente','nonapposee'].includes(x.a));let html=`<div class="hero"><h1>Analyse — ${p}</h1><p>${bad.length} anomalie(s) sélectionnée(s).</p></div>`;if(!bad.length)html+=`<div class="notice ok"><b>Aucune anomalie sélectionnée.</b><br>Le contrôle n’est pas juridiquement « validé » par l’application : compléter les constatations réelles et appliquer les textes en vigueur.</div>`;bad.forEach(x=>{const maps=mapFor(p,x.it[0],x.a);html+=`<div class="card"><h3>${x.it[0]}</h3><p class="small">${statusText(x.a)}</p>${maps.length?maps.map(n=>`<div class="nrow"><span class="ncode">NATINF ${n[0]}</span> <span class="tag">${n[3]}</span><div class="nname">${n[2]}</div><div class="small">${n[4]}</div><div class="small"><b>${n[5]}</b></div></div>`).join(''):`<p>Pas de correspondance automatique dans le référentiel intégré. Décrire précisément les faits et vérifier le texte/NATINF à jour.</p>`}</div>`});const reportCandidates=[];bad.forEach(x=>{const maps=mapFor(p,x.it[0],x.a);maps.forEach(n=>{if(!reportCandidates.some(c=>c.natinf===n[0]))reportCandidates.push({natinf:n[0],anomaly:x.it[0],status:x.a})});if(!maps.length&&!reportCandidates.some(c=>c.anomaly===x.it[0]))reportCandidates.push({natinf:'',anomaly:x.it[0],status:x.a})});window.pendingReportCandidates=reportCandidates;html+=`<div class="notice">Toujours distinguer le fait constaté, le document présenté, la déclaration du conducteur et la qualification juridique. En cas de délit ou de doute sérieux : rendre compte à l’OPJ.</div><button class="primary" onclick="openReportFromCandidates()">📝 Générer le rapport à partir du contrôle</button>`;const box=document.getElementById('analysis');if(!box)throw new Error('Zone d’analyse introuvable');box.innerHTML=html;document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById('resultView').classList.add('active');window.scrollTo(0,0)}catch(e){console.error('T3P analyse:',e);alert('Impossible d’afficher l’analyse. Rechargez l’application puis réessayez.')}}
function escapeHtml(x){return String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function escapeJs(x){return String(x||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'")}
function statusText(a){return ({absent:'Absent',nonconforme:'Non conforme',nonpresente:'Non présenté',nonapposee:'Non apposée'})[a]||a}
function mapFor(p,label,status){const m=[];const add=c=>DATA.natinf.filter(n=>n[0]===c).forEach(n=>m.push(n));if(label.includes('aptitude')){if(p==='Taxi')add('22874');else if(p==='VTC')add('27746');else if(p==='LOTI')add('22877');else if(p==='VMDTR')add('28159');}if(label.includes('présentation')||label.includes('presentation')){if(p==='Taxi')add('30763');else if(p==='VTC')add('27949');else if(p==='LOTI')add('30763');else if(p==='VMDTR')add('28156');}if(label.includes('apposition')||label.includes('apposée')||label.includes('apposee'))add('30760');if(label==='Carte professionnelle taxi'&&status==='absent')add('30761');if(label==='Carte professionnelle VTC'&&status==='absent')add('27711');if(label==='Carte professionnelle VMDTR'&&status==='absent')add('28160');if(label==='Inscription REVTC')add('30756');if(label==='Macaron / vignette avant')add('30899');if(label==='Macaron / vignette arrière')add('30900');if(label==='Numéro REVTC sur la vignette')add('30897');if(label.includes('Réservation préalable')&&p==='VTC')add('30767');if(label.includes('Contrôle technique')){if(p==='Taxi')add('22736');else if(p==='VTC'||p==='LOTI')add('13198');}if(label.includes('Assurance transport')||label==='RC professionnelle')add('31058');if(label==='ADS / autorisation de stationnement')add('25354');if(label==='Imprimante / note')add('31002');if(label==='Terminal de paiement électronique')add('31003');if(label==='Dispositif lumineux TAXI')add('31000');if(label==='Plaque ADS')add('31001');if(label==='Taximètre')add('30999');if(label==='Affichage des tarifs'||label==='Forfait éventuel')add('2913');if(label==='Copie conforme')add('27777');if(label.includes('Billet collectif'))add('30775');return m.filter((n,i,a)=>a.findIndex(x=>x[0]===n[0])===i)}
function renderNatinf(){filterNatinf('')}
function filterNatinf(q){q=q.toLowerCase();document.getElementById('natinfList').innerHTML=DATA.natinf.filter(n=>n.join(' ').toLowerCase().includes(q)).map(n=>`<div class="nrow"><div class="title-row"><div><span class="ncode">NATINF ${n[0]}</span> <span class="tag">${n[1]}</span></div><button class="fav-inline ${isNatinfFav(n[0])?'is-fav':''}" onclick="toggleFav('${n[0]}')" aria-label="Favori">${isNatinfFav(n[0])?'★':'☆'}</button></div><div class="nname">${n[2]}</div><div class="small">${n[3]} · ${n[4]}</div><div class="small">${n[5]}</div></div>`).join('')||'<div class="notice">Aucun résultat.</div>'}
function isNatinfFav(code){return JSON.parse(localStorage.getItem('t3p-fav')||'[]').includes(code)}
function toggleFav(code){let f=JSON.parse(localStorage.getItem('t3p-fav')||'[]');f=f.includes(code)?f.filter(x=>x!==code):[...f,code];localStorage.setItem('t3p-fav',JSON.stringify(f));renderFav();filterNatinf(document.getElementById('natinfSearch')?.value||'')}
function showNatinf(code){show('natinf');filterNatinf(code)}
function renderFav(){const f=JSON.parse(localStorage.getItem('t3p-fav')||'[]');const fi=JSON.parse(localStorage.getItem('t3p-fav-items')||'[]');const box=document.getElementById('favorites');if(!box)return;const section=(title,icon,items,empty)=>`<div class="detail-section"><h3>${icon} ${title}</h3>${items.length?'<div class="stack">'+items.join('')+'</div>':`<div class="small">${empty}</div>`}</div>`;const nat=f.map(c=>DATA.natinf.find(x=>x[0]===c)).filter(Boolean);const ref=fi.filter(id=>id.startsWith('reflex:')).map(id=>id.slice(7)).filter(k=>REFLEXES[k]);const veh=fi.filter(id=>id.startsWith('vehicle:')).map(id=>id.slice(8)).filter(k=>VEHICLES[k]);box.innerHTML=section('NATINF','⚖️',nat.map(n=>`<button class="action" onclick="show('natinf');filterNatinf('${n[0]}')"><strong>NATINF ${n[0]}</strong><span class="small">${n[2]}</span></button>`),'Aucun NATINF favori.')+section('Fiches réflexes','⚡',ref.map(k=>{const v=REFLEXES[k];return `<button class="action" onclick="show('reflexes');showReflex('${k}')"><strong>${v.icon} ${v.title}</strong><span class="small">Fiche réflexe favorite</span></button>`}),'Aucune fiche réflexe favorite.')+section('Fiches véhicules','🚗',veh.map(k=>{const v=VEHICLES[k];return `<button class="action" onclick="show('vehicles');showVehicle('${k}')"><strong>${v.icon} ${v.title}</strong><span class="small">Fiche véhicule favorite</span></button>`}),'Aucune fiche véhicule favorite.');}
function searchAll(q){q=q.trim().toLowerCase();const box=document.getElementById('searchResults');if(!q){box.innerHTML='';return}let out=[];DATA.natinf.filter(n=>n.join(' ').toLowerCase().includes(q)).slice(0,6).forEach(n=>out.push(`<button class="action" onclick="showNatinf('${n[0]}')"><strong>NATINF ${n[0]}</strong><span class="small">${n[2]}</span></button>`));Object.entries(DATA.checklists).forEach(([p,arr])=>arr.filter(it=>it.join(' ').toLowerCase().includes(q)).slice(0,3).forEach(it=>out.push(`<button class="action" onclick="startControl('${p}')"><strong>${p} — ${it[0]}</strong><span class="small">${it[2]}</span></button>`)));if(out.length)box.innerHTML=out.slice(0,10).join('');else box.innerHTML='<div class="small">Aucun résultat.</div>'}
function procedureFor(n){
  if(!n)return 'Vérifier la procédure applicable avant verbalisation.';
  const t=String(n[5]||'').trim();
  return t||'Vérifier la procédure applicable avant verbalisation.';
}
function openReportFromCurrentControl(){
  const p=current?.profession||'';
  const items=DATA.checklists[p]||[];
  const bad=items.map((it,i)=>({it,i,a:current.answers[i]})).filter(x=>['absent','nonconforme','nonpresente','nonapposee'].includes(x.a));
  const c=[];
  bad.forEach(x=>{
    const maps=mapFor(p,x.it[0],x.a);
    maps.forEach(n=>{if(!c.some(z=>z.natinf===n[0]))c.push({natinf:n[0],anomaly:x.it[0],status:x.a})});
    if(!maps.length&&!c.some(z=>z.anomaly===x.it[0]))c.push({natinf:'',anomaly:x.it[0],status:x.a});
  });
  window.pendingReportCandidates=c;
  openReportFromCandidates();
}
let reportMeta={natinf:'',anomaly:'',status:''};
function nowLocalInput(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function openReport(code='',anomaly='',status=''){reportMeta={natinf:code||'',anomaly:anomaly||'',status:status||''};window.reportSelectedNatinfs=code?[code]:[];document.getElementById('r_datetime').value=nowLocalInput();const n=DATA.natinf.find(x=>x[0]===reportMeta.natinf);document.getElementById('reportTarget').innerHTML=n?`<div class="notice"><b>NATINF ${n[0]}</b> — ${n[2]}<br><span class="small">${n[4]} · ${procedureFor(n)}</span></div>`:reportMeta.anomaly?`<div class="notice"><b>Fait sélectionné :</b> ${reportMeta.anomaly}<br><span class="small">Décrire les faits puis vérifier le NATINF avant verbalisation.</span></div>`:`<div class="notice">Trame libre de rédaction factuelle.</div>`;document.getElementById('reportOutput').classList.add('hidden');document.getElementById('reportOutput').textContent='';document.getElementById('reportWarnings').innerHTML='';show('report')}
function openReportFromCandidates(){const c=window.pendingReportCandidates||[];reportMeta={natinf:'',anomaly:'',status:''};window.reportSelectedNatinfs=[];document.getElementById('r_datetime').value=nowLocalInput();const rows=c.map(x=>{const n=DATA.natinf.find(z=>z[0]===x.natinf);return `<label class="report-check"><input type="checkbox" class="report-natinf" value="${x.natinf}" data-anomaly="${escapeHtml(x.anomaly||'')}"><span><b>${n?'NATINF '+n[0]:'Fait constaté'}</b> — ${escapeHtml(x.anomaly||'')}${n?`<br><span class="small">${escapeHtml(n[2])} · ${escapeHtml(procedureFor(n))}</span>`:''}</span></label>`}).join('');document.getElementById('reportTarget').innerHTML=`<div class="notice">Sélectionner les faits et NATINF à intégrer au rapport. Plusieurs infractions peuvent être cochées. Rien n’est imposé.</div>${rows?`<div class="card"><h3>Infractions / faits à intégrer</h3><div class="report-checks">${rows}</div></div>`:`<div class="notice">Aucune anomalie issue du contrôle. Le rapport peut rester libre.</div>`}`;document.getElementById('reportOutput').classList.add('hidden');document.getElementById('reportOutput').textContent='';document.getElementById('reportWarnings').innerHTML='';show('report')}
async function geoReport(){const box=document.getElementById('r_geo');if(!navigator.geolocation){box.textContent='Géolocalisation indisponible sur cet appareil.';return}box.textContent='Localisation en cours…';navigator.geolocation.getCurrentPosition(async pos=>{const lat=pos.coords.latitude.toFixed(6),lon=pos.coords.longitude.toFixed(6);box.dataset.lat=lat;box.dataset.lon=lon;try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lon)}&zoom=18&addressdetails=1`,{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('reverse geocoding');const d=await r.json();box.dataset.address=d.display_name||'';const a=d.address||{};const street=[a.house_number,a.road||a.pedestrian||a.cycleway||a.path].filter(Boolean).join(' ');const city=[a.postcode,a.city||a.town||a.village||a.municipality].filter(Boolean).join(' ');const concise=[street,city].filter(Boolean).join(', ');const address=concise||d.display_name||'';box.dataset.address=address;if(address){document.getElementById('r_place').value=address;box.textContent=`Adresse GPS : ${address} — modifiable manuellement.`;}else{box.textContent=`Coordonnées GPS relevées : ${lat}, ${lon} — saisir/modifier le lieu manuellement.`;}}catch(e){box.textContent=`Coordonnées GPS relevées : ${lat}, ${lon}. Adresse indisponible : saisir le lieu manuellement.`;}},err=>{box.textContent='Géolocalisation refusée ou indisponible. Saisir le lieu manuellement.'},{enableHighAccuracy:true,timeout:10000,maximumAge:60000})}
function val(id){const e=document.getElementById(id);return e?String(e.value||'').trim():''}
let reportPhotos=[];
function addReportPhotos(files){const incoming=Array.from(files||[]);reportPhotos=[...reportPhotos,...incoming].slice(0,12);renderReportPhotos()}
function renderReportPhotos(){const box=document.getElementById('photoList');if(!box)return;box.innerHTML=reportPhotos.length?reportPhotos.map((f,i)=>`<div class="photo-item"><span class="small">📷 ${i+1}. ${f.name}</span><button type="button" class="secondary photo-remove" onclick="removeReportPhoto(${i})">Supprimer</button></div>`).join(''):'Aucune photo sélectionnée.'}
function removeReportPhoto(i){reportPhotos.splice(i,1);renderReportPhotos()}
function chooseReportPhoto(){document.getElementById('reportPicker').click()}
function makeReportText(){generateReport();return document.getElementById('reportOutput')?.textContent||''}
async function shareReport(){const text=makeReportText();if(!text)return;const stamp=new Date().toISOString().replace(/[:.]/g,'-');const reportFile=new File([text],`rapport-t3p-${stamp}.txt`,{type:'text/plain'});const files=[reportFile,...reportPhotos];try{if(navigator.share && (!navigator.canShare || navigator.canShare({files}))){await navigator.share({title:'Rapport contrôle T3P',text:'Rapport de contrôle T3P',files});document.getElementById('reportWarnings').innerHTML='<div class="notice ok">Rapport et photos transmis au menu de partage.</div>'}else{const a=document.createElement('a');a.href=URL.createObjectURL(reportFile);a.download=reportFile.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);document.getElementById('reportWarnings').innerHTML='<div class="notice">Le partage de fichiers n’est pas disponible sur ce navigateur. Le rapport a été enregistré ; joindre les photos manuellement dans votre e-mail.</div>'}}catch(e){document.getElementById('reportWarnings').innerHTML='<div class="notice">Partage annulé ou indisponible. Le rapport reste disponible ci-dessous.</div>'}}
function generateReport(){
const selected=Array.from(document.querySelectorAll('.report-natinf:checked')).map(e=>e.value).filter(Boolean);
const selectedN=selected.map(c=>DATA.natinf.find(x=>x[0]===c)).filter(Boolean);
const required=[['r_datetime','date/heure'],['r_place','lieu'],['r_driver','conducteur'],['r_facts','constatations matérielles']];
const missing=required.filter(([id])=>!val(id)).map(([,name])=>name);
const warnings=document.getElementById('reportWarnings');
if(missing.length){warnings.innerHTML=`<div class="notice danger"><b>Document non généré :</b> compléter au minimum ${missing.join(', ')}.</div>`;document.getElementById('reportOutput').classList.add('hidden');return}
const isPV=selectedN.some(n=>String(n[3]||'').includes('C5') || String(n[3]||'').toLowerCase().includes('délit'));
const title=isPV?'PROCÈS-VERBAL':'RAPPORT';
const geo=document.getElementById('r_geo');
const geoTxt=geo?.dataset.lat?`Coordonnées GPS : ${geo.dataset.lat}, ${geo.dataset.lon}${geo.dataset.address?'\nAdresse GPS : '+geo.dataset.address:''}`:'';
let out=`RÉPUBLIQUE FRANÇAISE\n\n${val('r_commune')||'POLICE MUNICIPALE'}\n\nRÉFÉRENCES\nN° : ${val('r_ref')||'XX/20XX'}\nObjet : ${val('r_objet')||'Contrôle T3P'}\n\n${title}\n\n`;
out+=`L’an deux mille vingt-six, le ${val('r_datetime')}.\n\nNous, ${val('r_agents')||'[grade, nom, matricule — agent assistant, matricule]'}, agents de police judiciaire adjoints, en service à ${val('r_commune')||'[commune / service]'}, constatons les faits suivants, conformément à nos compétences et aux circonstances ayant régulièrement engagé notre intervention.\n\n`;
if(val('r_objet'))out+=`OBJET\n${val('r_objet')}\n\n`;
out+=`LIEU\n${val('r_place')}\n${geoTxt?geoTxt+'\n':''}\nVÉHICULE\n${val('r_plate')||'[immatriculation]'}${val('r_vehicle')?' — '+val('r_vehicle'):''}\n\nCONDUCTEUR\n${val('r_driver')}\n`;
if(val('r_operator'))out+=`Exploitant / entreprise : ${val('r_operator')}\n`;
if(val('r_identity'))out+=`Mode d’établissement de l’identité : ${val('r_identity')}\n`;
if(selectedN.length)out+=`\nQUALIFICATION / RÉFÉRENCES À VÉRIFIER\n${selectedN.map(n=>`NATINF ${n[0]} — ${n[2]}\nNature : ${n[3]}\nTexte de référence : ${n[4]}`).join('\n\n')}\n`;
out+=`\nCONSTATATIONS\n${val('r_facts')}\n`;
if(val('r_statements'))out+=`\nDÉCLARATIONS / ÉLÉMENTS RECUEILLIS\n${val('r_statements')}\n`;
if(val('r_checks'))out+=`\nVÉRIFICATIONS EFFECTUÉES\n${val('r_checks')}\n`;
if(val('r_notes'))out+=`\nOBSERVATIONS COMPLÉMENTAIRES\n${val('r_notes')}\n`;
if(reportPhotos.length)out+=`\nPIÈCES / PHOTOGRAPHIES JOINTES\n${reportPhotos.map((f,i)=>`${i+1}. ${f.name}`).join('\n')}\n`;
const ident=[val('r_idnom')&&`Nom : ${val('r_idnom')}`,val('r_idprenom')&&`Prénom : ${val('r_idprenom')}`,val('r_iddob')&&`Date de naissance : ${val('r_iddob')}`,val('r_idaddr')&&`Adresse : ${val('r_idaddr')}`,val('r_idpiece')&&`N° pièce ID : ${val('r_idpiece')}`].filter(Boolean).join('\n');
if(ident)out+=`\nIDENTITÉ\n${ident}\n`;
if(val('r_dest'))out+=`\nDESTINATAIRE(S)\n${val('r_dest')}\n`;
out+=`\n${title==='PROCÈS-VERBAL'?'Le présent procès-verbal est établi au vu des constatations personnellement effectuées.':'Le présent rapport est établi au vu des constatations personnellement effectuées et des éléments recueillis.'}\n\nLe rédacteur : ____________________\nL’assistant : ____________________\n`;
const el=document.getElementById('reportOutput');el.textContent=out;el.classList.remove('hidden');warnings.innerHTML=`<div class="notice ok">${title} généré à partir du modèle vierge. Relire intégralement, supprimer tout élément non constaté et vérifier la qualification/NATINF avant utilisation.</div>`}

async function copyReport(){const el=document.getElementById('reportOutput');if(!el.textContent){generateReport();if(!el.textContent)return}try{await navigator.clipboard.writeText(el.textContent);document.getElementById('reportWarnings').innerHTML='<div class="notice ok">Rapport copié dans le presse-papiers.</div>'}catch(e){document.getElementById('reportWarnings').innerHTML='<div class="notice">Copie automatique indisponible : sélectionner et copier le texte généré.</div>'}}
function showManual(i){const el=document.getElementById('manualText');el.classList.remove('hidden');el.textContent=DATA.sections[i][0]+'\n\n'+DATA.sections[i][1];el.scrollIntoView({behavior:'auto',block:'start'})}
function renderResources(){document.getElementById('resourceList').innerHTML=DATA.resources.map(r=>`<div class="card"><h3>${r[0]}</h3><p>${r[2]}</p><a href="${r[1]}" target="_blank" rel="noopener" style="color:var(--accent);word-break:break-all">Ouvrir la ressource officielle</a></div>`).join('')}
let feedbackMode='bug';function openBugReport(){feedbackMode='bug';document.querySelector('#bugOverlay h2').textContent='🐞 Signaler un bug';document.querySelector('#bugOverlay p').textContent='Décrivez le problème rencontré. Votre application e-mail s’ouvrira avec un message prérempli.';document.getElementById('bugText').value='';document.getElementById('bugOverlay').classList.add('show');setTimeout(()=>document.getElementById('bugText').focus(),50)} function openFeedback(){feedbackMode='feedback';document.querySelector('#bugOverlay h2').textContent='💬 Suggestion / commentaire';document.querySelector('#bugOverlay p').textContent='Votre application e-mail s’ouvrira avec un message prérempli.';document.getElementById('bugText').value='';document.getElementById('bugOverlay').classList.add('show');setTimeout(()=>document.getElementById('bugText').focus(),50)} function closeBugReport(e){if(e&&e.target!==document.getElementById('bugOverlay'))return;document.getElementById('bugOverlay').classList.remove('show')} function sendBugReport(){const text=document.getElementById('bugText').value.trim();const subject=feedbackMode==='bug'?'Signalement de bug — Application T3P':'Suggestion / commentaire — Application T3P';const body=feedbackMode==='bug'?`Bonjour,\n\nJe souhaite signaler un problème concernant l’application T3P.\n\nDescription du problème :\n${text||'[À compléter]'}\n\nAppareil / navigateur :\n[À compléter]\n\nMerci.`:`Bonjour,\n\nJe souhaite envoyer une suggestion ou un commentaire concernant l’application T3P.\n\nMessage :\n${text||'[À compléter]'}\n\nAppareil / navigateur :\n[À compléter]\n\nMerci.`;window.location.href='mailto:retour.guidet3p@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}
